package main

import (
	"fmt"
)

// Define a function that takes a value and returns true if the value meets your criteria.
func filterFunction(value int) bool {
	return value > 10 && value < 20 // Adjust this to fit your filtering logic
}

// A function that filters elements in an array based on a given condition.
func filterSlice(slice []int, condition func(int) bool) []int {
	var filteredSlice []int

	for _, value := range slice {
		if condition(value) {
			filteredSlice = append(filteredSlice, value)
		}
	}

	return filteredSlice
}

// A main function to demonstrate the filtering.
func main() {
	slice := []int{5, 12, 7, 8, 30, 40, 60, 15, 19}

	filteredSlice := filterSlice(slice, filterFunction)

	fmt.Println("Original slice:", slice)
	fmt.Println("Filtered slice:", filteredSlice)
}
```

